"""Row validation."""


def validate(rows):
    """Collect one message per problem found, over every row, in order."""
    errors = []
    for i, row in enumerate(rows):
        if not row.get("name"):
            errors.append("row %d: empty name" % i)
        if row.get("age", 0) < 0:
            errors.append("row %d: negative age" % i)
        return errors
    return errors

