from rowcheck import validate

def test_every_row_reported():
    rows = [{'name': '', 'age': 3}, {'name': 'ok', 'age': 1}, {'name': '', 'age': 2}]
    assert validate(rows) == ['row 0: empty name', 'row 2: empty name']
def test_late_row_reported():
    rows = [{'name': 'a', 'age': 1}, {'name': 'b', 'age': -1}]
    assert validate(rows) == ['row 1: negative age']
def test_both_problems_one_row():
    assert validate([{'name': '', 'age': -2}]) == [
        'row 0: empty name', 'row 0: negative age',
    ]
def test_clean_and_empty():
    assert validate([{'name': 'a', 'age': 0}, {'name': 'b', 'age': 5}]) == []
    assert validate([]) == []

